bool PageStubDispatch::Accept(
    Page* impl,
    mojo::Message* message) {
  switch (static_cast<messages::Page>(message->header()->name)) {
    case messages::Page::kOnLocalDataCountChanged: {
      DCHECK(message->is_serialized());
      internal::Page_OnLocalDataCountChanged_Params_Data* params =
          reinterpret_cast<internal::Page_OnLocalDataCountChanged_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.0
      bool success = true;
      int32_t p_local_data_count{};
      Page_OnLocalDataCountChanged_ParamsDataView input_data_view(params, message);
      
      if (success)
        p_local_data_count = input_data_view.local_data_count();
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnLocalDataCountChanged(        
        std::move(p_local_data_count));
      return true;
    }
  }
  return false;
}

